import * as THREE from 'three';
import { MTLLoader } from 'three/examples/jsm/loaders/MTLLoader';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';

class EarthViewer {
    constructor() {
        this.scene = new THREE.Scene();
        this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        this.renderer = new THREE.WebGLRenderer({ antialias: true });
        
        this.init();
        this.setupLighting();
        this.loadModel();
        this.setupEventListeners();
    }
    
    init() {
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        this.renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(this.renderer.domElement);
        
        this.camera.position.set(0, 0, 7);
        this.camera.lookAt(0, 0, 0);
    }
    
    setupLighting() {
        // Main directional light (like sunlight)
        const directionalLight = new THREE.DirectionalLight(0xffffff, 1.0);
        directionalLight.position.set(5, 3, 5);
        this.scene.add(directionalLight);
        
        // Ambient light for general illumination
        const ambientLight = new THREE.AmbientLight(0x404040);
        this.scene.add(ambientLight);
        
        // Add a subtle blue backlight
        const backLight = new THREE.DirectionalLight(0x2233ff, 0.3);
        backLight.position.set(-5, 0, -5);
        this.scene.add(backLight);
    }
    
    loadModel() {
        const mtlLoader = new MTLLoader();
        mtlLoader.load('assets/earth.mtl', (materials) => {
            materials.preload();
            
            const objLoader = new OBJLoader();
            objLoader.setMaterials(materials);
            objLoader.load('assets/earth.obj', (object) => {
                this.earthModel = object;
                
                // Apply double-sided materials
                object.traverse((child) => {
                    if (child instanceof THREE.Mesh) {
                        child.material.side = THREE.DoubleSide;
                    }
                });
                
                this.scene.add(object);
                this.animate();
            });
        });
    }
    
    setupEventListeners() {
        // Handle window resize
        window.addEventListener('resize', () => {
            this.camera.aspect = window.innerWidth / window.innerHeight;
            this.camera.updateProjectionMatrix();
            this.renderer.setSize(window.innerWidth, window.innerHeight);
        });
        
        // Optional: Add mouse interaction
        document.addEventListener('mousemove', (event) => {
            if (this.earthModel) {
                // Subtle rotation based on mouse position
                const mouseX = (event.clientX / window.innerWidth) * 2 - 1;
                const mouseY = -(event.clientY / window.innerHeight) * 2 + 1;
                
                this.earthModel.rotation.y = mouseX * 0.5;
                this.earthModel.rotation.x = mouseY * 0.2;
            }
        });
    }
    
    animate() {
        requestAnimationFrame(this.animate.bind(this));
        
        if (this.earthModel) {
            // Only apply automatic rotation if no mouse interaction
            if (!this.mouseInteracting) {
                this.earthModel.rotation.y += 0.005;
            }
        }
        
        this.renderer.render(this.scene, this.camera);
    }
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    new EarthViewer();
});